with test_seed(id, title, slug, description, subject, time_limit_minutes) as (
    values
        ('72111111-1111-4111-8111-111111111111'::uuid, 'ОДАТ/ТГО: критическое мышление', 'kta-odat-critical-thinking', 'Тренировочный тест по чтению условия, выводам, допущениям и работе с аргументами в формате подготовки к КТА.', 'ОДАТ / ТГО', 18),
        ('72111111-1111-4111-8111-111111111112'::uuid, 'КТА: аналитическое мышление и логика', 'kta-logic-analytics', 'Задания на последовательности, ограничения, таблицы, множества и проверку логического вывода.', 'Логика', 20),
        ('72111111-1111-4111-8111-111111111113'::uuid, 'Английский язык КТА: grammar and reading', 'kta-english-grammar-reading', 'Мини-тест по грамматике, академической лексике и пониманию коротких текстов для КТА в магистратуру.', 'Английский язык', 18),
        ('72111111-1111-4111-8111-111111111114'::uuid, 'Профильный предмет: педагогика и психология', 'kta-profile-pedagogy-psychology', 'Базовая диагностика по педагогике, психологии обучения, мотивации, оцениванию и исследовательскому мышлению.', 'Профильный предмет', 20),
        ('72111111-1111-4111-8111-111111111115'::uuid, 'КТА мини-диагностика: смешанный формат', 'kta-mini-diagnostic', 'Смешанный пробный тест: логика, ОДАТ, английский и профильные вопросы для быстрой оценки готовности.', 'Смешанный КТА', 25)
)
insert into tests(id, title, slug, description, subject, time_limit_minutes, status, created_by, created_at, updated_at)
select id, title, slug, description, subject, time_limit_minutes, 'PUBLISHED',
       (select users.id from users join user_roles on user_roles.user_id = users.id join roles on roles.id = user_roles.role_id where roles.name = 'ADMIN' order by users.created_at asc limit 1),
       now(), now()
from test_seed
on conflict (slug) do update
set title = excluded.title,
    description = excluded.description,
    subject = excluded.subject,
    time_limit_minutes = excluded.time_limit_minutes,
    status = excluded.status,
    updated_at = now();

with question_seed(id, test_slug, question_text, question_type, explanation, order_number) as (
    values
        ('72211111-1111-4111-8111-111111111111'::uuid, 'kta-odat-critical-thinking', 'Все студенты, которые регулярно разбирают ошибки, повышают точность. Данияр регулярно разбирает ошибки. Какой вывод следует из условий?', 'SINGLE_CHOICE', 'Если все участники группы обладают свойством, а Данияр входит в эту группу, то свойство относится и к нему.', 1),
        ('72211111-1111-4111-8111-111111111112'::uuid, 'kta-odat-critical-thinking', 'В отчете сказано: часть слушателей прошла пробный тест до курса. Какое утверждение обязательно верно?', 'SINGLE_CHOICE', 'Фраза часть слушателей означает, что хотя бы один слушатель прошел пробный тест, но не доказывает, что прошли все.', 2),
        ('72211111-1111-4111-8111-111111111113'::uuid, 'kta-odat-critical-thinking', 'Аргумент: Чтобы повысить балл, нужно чаще тренироваться в условиях таймера. Какой вариант лучше всего усиливает аргумент?', 'SINGLE_CHOICE', 'Данные о росте результата после тренировок с таймером прямо поддерживают связь между методом и баллом.', 3),
        ('72211111-1111-4111-8111-111111111114'::uuid, 'kta-odat-critical-thinking', 'Какое допущение скрыто в выводе: Если студент выучил теорию, он обязательно решит практические задания?', 'SINGLE_CHOICE', 'Вывод предполагает, что знания теории достаточно для практики, хотя это не всегда верно.', 4),
        ('72211111-1111-4111-8111-111111111115'::uuid, 'kta-odat-critical-thinking', 'Текст: Онлайн-курс помогает тем, кто учится регулярно. Какой вывод нельзя делать только из этой фразы?', 'SINGLE_CHOICE', 'Из фразы не следует, что курс не помогает никому другому или что все нерегулярные студенты провалятся.', 5),
        ('72211111-1111-4111-8111-111111111116'::uuid, 'kta-odat-critical-thinking', 'Какие признаки помогают отличить строгий вывод от предположения?', 'MULTIPLE_CHOICE', 'Строгий вывод опирается на данные условия и не добавляет новую неподтвержденную информацию.', 6),

        ('72211111-1111-4111-8111-111111111121'::uuid, 'kta-logic-analytics', 'Продолжите ряд: 3, 6, 12, 24, ...', 'SINGLE_CHOICE', 'Каждое число умножается на 2, значит после 24 идет 48.', 1),
        ('72211111-1111-4111-8111-111111111122'::uuid, 'kta-logic-analytics', 'Продолжите ряд: 2, 5, 10, 17, 26, ...', 'SINGLE_CHOICE', 'Разности равны 3, 5, 7, 9, значит следующая разность 11, а ответ 37.', 2),
        ('72211111-1111-4111-8111-111111111123'::uuid, 'kta-logic-analytics', 'В группе А, Б и В. А выше Б, Б выше В. Кто самый низкий?', 'SINGLE_CHOICE', 'Если А выше Б, а Б выше В, то В ниже обоих.', 3),
        ('72211111-1111-4111-8111-111111111124'::uuid, 'kta-logic-analytics', 'Из 30 слушателей 18 изучают английский, 16 изучают логику, 8 изучают оба предмета. Сколько изучают хотя бы один из этих предметов?', 'SINGLE_CHOICE', 'По формуле объединения: 18 + 16 - 8 = 26.', 4),
        ('72211111-1111-4111-8111-111111111125'::uuid, 'kta-logic-analytics', 'Если встреча началась на 15 минут позже и длилась 50 минут, она закончилась в 12:05. Во сколько должна была начаться встреча по плану?', 'SINGLE_CHOICE', 'Фактически встреча началась в 11:15, значит по плану она должна была начаться в 11:00.', 5),
        ('72211111-1111-4111-8111-111111111126'::uuid, 'kta-logic-analytics', 'Какие способы полезны для задач с несколькими ограничениями?', 'MULTIPLE_CHOICE', 'Таблица, исключение невозможных вариантов и проверка ответа по всем условиям уменьшают риск ошибки.', 6),

        ('72211111-1111-4111-8111-111111111131'::uuid, 'kta-english-grammar-reading', 'Choose the correct sentence.', 'SINGLE_CHOICE', 'Present perfect is used with experience up to now: has completed.', 1),
        ('72211111-1111-4111-8111-111111111132'::uuid, 'kta-english-grammar-reading', 'Choose the best word: The results were ___ because the sample was too small.', 'SINGLE_CHOICE', 'Inconclusive means not leading to a definite result.', 2),
        ('72211111-1111-4111-8111-111111111133'::uuid, 'kta-english-grammar-reading', 'Read the sentence: The study suggests a link, but it does not prove causation. What is the main idea?', 'SINGLE_CHOICE', 'The sentence says there may be a relationship, but cause and effect are not proven.', 3),
        ('72211111-1111-4111-8111-111111111134'::uuid, 'kta-english-grammar-reading', 'Choose the correct form: If she had more time, she ___ more practice tests.', 'SINGLE_CHOICE', 'Second conditional uses would + base verb.', 4),
        ('72211111-1111-4111-8111-111111111135'::uuid, 'kta-english-grammar-reading', 'Which phrase shows contrast?', 'SINGLE_CHOICE', 'However is a contrast marker.', 5),
        ('72211111-1111-4111-8111-111111111136'::uuid, 'kta-english-grammar-reading', 'Which strategies help answer reading questions?', 'MULTIPLE_CHOICE', 'The useful strategies are finding the main idea, locating details, and checking context. Translating every word wastes time.', 6),

        ('72211111-1111-4111-8111-111111111141'::uuid, 'kta-profile-pedagogy-psychology', 'Какой принцип обучения означает движение от простого материала к более сложному?', 'SINGLE_CHOICE', 'Принцип доступности и последовательности требует учитывать уровень обучающегося и усложнять материал постепенно.', 1),
        ('72211111-1111-4111-8111-111111111142'::uuid, 'kta-profile-pedagogy-psychology', 'Что лучше всего отражает формативное оценивание?', 'SINGLE_CHOICE', 'Формативное оценивание помогает учиться в процессе и дает обратную связь до итоговой оценки.', 2),
        ('72211111-1111-4111-8111-111111111143'::uuid, 'kta-profile-pedagogy-psychology', 'Какая мотивация считается внутренней?', 'SINGLE_CHOICE', 'Внутренняя мотивация связана с интересом к деятельности, а не только с внешней наградой.', 3),
        ('72211111-1111-4111-8111-111111111144'::uuid, 'kta-profile-pedagogy-psychology', 'Что является примером валидности теста?', 'SINGLE_CHOICE', 'Валидность означает, что инструмент измеряет именно то качество или знание, для которого он создан.', 4),
        ('72211111-1111-4111-8111-111111111145'::uuid, 'kta-profile-pedagogy-psychology', 'Какие действия относятся к исследовательскому подходу в образовании?', 'MULTIPLE_CHOICE', 'Исследовательский подход включает вопрос, сбор данных и анализ результатов; готовый ответ без проверки не является исследованием.', 5),
        ('72211111-1111-4111-8111-111111111146'::uuid, 'kta-profile-pedagogy-psychology', 'Какой метод помогает снизить когнитивную перегрузку?', 'SINGLE_CHOICE', 'Разделение сложного материала на небольшие шаги снижает нагрузку на рабочую память.', 6),

        ('72211111-1111-4111-8111-111111111151'::uuid, 'kta-mini-diagnostic', 'Логика: какое число лишнее в ряду 4, 8, 16, 20, 32?', 'SINGLE_CHOICE', 'Ряд строится умножением на 2: 4, 8, 16, 32. Число 20 нарушает закономерность.', 1),
        ('72211111-1111-4111-8111-111111111152'::uuid, 'kta-mini-diagnostic', 'ОДАТ: Все опубликованные тесты доступны студентам. Этот тест опубликован. Что следует?', 'SINGLE_CHOICE', 'По условию опубликованный тест доступен студентам, значит этот тест тоже доступен студентам.', 2),
        ('72211111-1111-4111-8111-111111111153'::uuid, 'kta-mini-diagnostic', 'English: Choose the correct option: The article ___ by many students every week.', 'SINGLE_CHOICE', 'Passive voice in present simple: is read.', 3),
        ('72211111-1111-4111-8111-111111111154'::uuid, 'kta-mini-diagnostic', 'Профиль: что лучше всего описывает обратную связь?', 'SINGLE_CHOICE', 'Обратная связь показывает, что получилось, что требует исправления и как улучшить результат.', 4),
        ('72211111-1111-4111-8111-111111111155'::uuid, 'kta-mini-diagnostic', 'Аналитика: у студента 5 тестов, средний балл 80. Какой суммарный балл по всем тестам?', 'SINGLE_CHOICE', 'Среднее значение умножается на количество тестов: 80 × 5 = 400.', 5),
        ('72211111-1111-4111-8111-111111111156'::uuid, 'kta-mini-diagnostic', 'Какие данные полезно сохранять после пробного теста?', 'MULTIPLE_CHOICE', 'Для реального прогресса важны балл, время, ошибки по темам и сложные вопросы; цвет кнопки не помогает анализу.', 6)
)
insert into questions(id, test_id, question_text, question_type, explanation, order_number, created_at, updated_at)
select question_seed.id, tests.id, question_seed.question_text, question_seed.question_type, question_seed.explanation, question_seed.order_number, now(), now()
from question_seed
join tests on tests.slug = question_seed.test_slug
on conflict (id) do update
set test_id = excluded.test_id,
    question_text = excluded.question_text,
    question_type = excluded.question_type,
    explanation = excluded.explanation,
    order_number = excluded.order_number,
    updated_at = now();

